const SB_WHICH = ["(40×9) + (8×9)", "40×9"].map((s) => ({ id: s, label: s }));
const sbW = (s, size) => {
  let w = 0;
  for (const ch of String(s)) w += /\d/.test(ch) ? 0.64 : ch === "," || ch === " " ? 0.3 : ch === "(" || ch === ")" ? 0.36 : 0.62;
  return w * size;
};
const sbCardW = (s) => Math.max(112, Math.round(sbW(s, T.xl) + 36));
const sbParts = (a) => {
  const s = String(a), out = [];
  for (let i = 0; i < s.length; i++) if (s[i] !== "0") out.push(Number(s[i]) * Math.pow(10, s.length - 1 - i));
  return out;
};
const sbSplit = (v) => {
  let core = v, z = 0;
  while (core > 0 && core % 10 === 0) {
    core /= 10;
    z++;
  }
  return { core, z };
};
const sbIsRound = (v) => String(v).replace(/0+$/, "").length === 1;
const sbRoundPair = (t) => sbIsRound(t[0] * t[1]) ? 0 : 1;
const sbChoice = (item, v) => {
  const c = (item.choices || []).find((x) => x.id === String(v) || String(x.label).toLowerCase() === String(v != null ? v : "").trim().toLowerCase());
  return c ? c.id : null;
};
const sbEqOf = (it) => {
  if (!it) return "";
  const k = it.kind;
  if (k === "onezero") return "× 1 and × 0";
  if (k === "one" || k === "zero") return indian(it.num) + " × " + (k === "one" ? 1 : 0);
  if (k === "order" || k === "group") return it.terms.map((t) => indian(t)).join(" × ");
  if (k === "expand" || k === "which") return indian(it.a) + " × " + it.m;
  if (k === "rail") return indian(it.a) + " × " + indian(it.b);
  return "";
};
const sbNoCarry = (L, s) => {
  const ds = String(L).split("").reverse().map(Number);
  let out = "";
  ds.forEach((d, k) => {
    const p = d * s;
    out = (k === ds.length - 1 ? String(p) : String(p % 10)) + out;
  });
  return Number(out);
};
